/* Entry point for tool/ffigen.dart: the GStreamer core, app (appsrc /
 * appsink) and pbutils (GstDiscoverer) headers the bindings are generated
 * from. The generated file only keeps the declarations tool/ffigen.dart
 * names, so adding a header here does not grow the bindings by itself. */
#include <glib.h>
#include <glib-object.h>
#include <gst/gst.h>
#include <gst/app/app.h>
#include <gst/pbutils/pbutils.h>
